const fragSrc = `precision mediump float;

	// x,y coordinates, given from the vertex shader
  varying vec2 vTexCoord;
	uniform vec2 iResolution;
	uniform float iTime;

	float sdCircle( vec2 p, float r ) {
    return length(p) - r;
	}
	float glowCircle(vec2 p, float r, float maxd) {
		return (maxd - min(maxd, sdCircle(p, r)))/maxd;
	}

#define PI 3.14159265

/**
 * Rand & Noise
 */

float random ( in vec2 st ) {
    return fract(sin(dot(st.xy, vec2(12.9898,78.233)))*43758.5453123);
}

// 2D Noise based on Morgan McGuire @morgan3d // https://www.shadertoy.com/view/4dS3Wd
float noise ( in vec2 st ) {
    vec2 i = floor(st);
    vec2 f = fract(st);

    // Four corners in 2D of a tile
    float a = random(i);
    float b = random(i + vec2(1.0, 0.0));
    float c = random(i + vec2(0.0, 1.0));
    float d = random(i + vec2(1.0, 1.0));

    // Smooth Interpolation

    // Cubic Hermine Curve.  Same as SmoothStep()
    vec2 u = f*f*(3.0-2.0*f);
    // u = smoothstep(0.,1.,f);

    // Mix 4 coorners percentages
    return mix(a, b, u.x) +
            (c - a)* u.y * (1.0 - u.x) +
            (d - b) * u.x * u.y;
}

// dist from rotating spot point center, radius, angle
float distCircRad( in vec2 uv, in vec2 c, in float r, in float a) {
   vec2 p = c + vec2(cos(a), sin(a)) * r;
   return length(uv - p);
}

// dist from segment point a, point b
float distSegment( in vec2 p, in vec2 a, in vec2 b ) {
	vec2 pa = p-a, ba = b-a;
	float h_c = clamp( dot(pa,ba)/dot(ba,ba), 0.0, 1.0 );
	float h = dot(pa,ba)/dot(ba,ba);
	float d = max(0., length( pa - ba * h ));
	float d_c = max(0., length( pa - ba * h_c ));
	//  double angle=atan2(v1.x*v2.x+v1.y*v2.y,v1.x*v2.y-v1.y*v2.x);
	if (h < 0.) d_c += abs(h);
	if (h > 1.) d_c += h - 1.;
	return d_c;
}


// https://easings.net/#easeInOutCubic
float easeInOutCubic(in float x) {
	return x < 0.5 ? 4. * x * x * x : 1. - pow(-2. * x + 2., 3.) / 2.;
}
float easeInElastic(in float x) {
	float c4 = (2. * PI) / 3.;
	return x == 0.
		? 0.
		: x == 1.
		? 1.
		: -pow(2., 10. * x - 10.) * sin((x * 10. - 10.75) * c4);
}
float easeDouble(in float x) {
	float v = easeInElastic(fract(x*2.)) * .5;
	return x < .5 ? v : .5 + v;
}

// uv, p1, p2, color, intensity
vec3 getClrNeonPts( in vec2 p, in vec2 a,  in vec2 b, in vec3 clr, in float its ) {
	float d = distSegment(p, a, b);
	float br =  its / d;
	br = min(1.86, br); // reduce overglue
	// br = smoothstep(.001, 0.91, br);
	return clr * br + vec3(1.) * br * .15;
}
// pos, length, angle, delta angle, color, intensity
vec3 getClrNeonBar( in vec2 p, in vec2 pos, in float len, in float ang, in float dag, in vec3 clr, in float its ) {
	// float f = easeInOutCubic(abs(.5-fract(iTime/PI))*2.);
	float f = easeDouble(fract(iTime/3.));
	float cag = ang + dag * f;
	vec2 w = vec2(cos(cag),sin(cag)) * len * 0.5;
	vec2  a = pos + w;
	vec2  b = pos - w;
	float d = distSegment(p, a, b);
	float br =  its / d;
	br = min(1.86, br); // reduce overglue
	// br = smoothstep(.001, 0.91, br);
	return clr * br + vec3(1.) * br * .15;
}

vec3 getColor(in vec2 pos, in float iTime) {
	float n = noise(pos);
	return n < sin(iTime*.5) * .5 ? vec3(.8, .2, .7) : n < sin(iTime*.3) ? vec3(.2, .7, .8)  : vec3(0.9);
}	

void main() {
	// Normalized pixel coordinates (from 0 to 1)
	vec2 uv = gl_FragCoord.xy/iResolution.xy - 0.5; // 0 center
	uv.x *= iResolution.x / iResolution.y; // aspect ratio

	vec3 clr = vec3(.01, .01, vTexCoord.y * .35);

	// clr += glowCircle(vec2(0.1, 0.2)-vTexCoord.xy, 0.001, 0.005) * vec3(1.,.8,.0);
	// clr += glowCircle(vec2(0.3, 0.15)-vTexCoord.xy, 0.001, 0.01) * vec3(1.,.8,.0);

	// grain: add or substract
	clr -= 0.3 * random(uv * PI + floor(iTime*5.));

	// bars
	for (float y = -.5; y <= .51; y += .15) {
		for (float x = -.5; x <= .51; x += .15) {
			vec2 pos = vec2(x + 0.05, y - 0.1);
			float n = noise(pos);
			vec3 col = n < sin(iTime * .5) * .3 ? vec3(.9) : n < sin(iTime * .5) ? vec3(.2, .7, .8)  : vec3(.8, .2, .7);
			float da = floor((n * 10.) * 10.) < 5. ? -PI : PI; // -.1 : .1
			clr += getClrNeonBar(uv, pos, 0.2, sign(da)*PI/4., da, col, 0.005);
		}
	}

	gl_FragColor = vec4(clr, 1.0);
}`;

